'use strict';
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Berlin'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('de-DE'):'offen';
const icons={leaf:'M12 20V10M12 15C4 15 3 10 4 5c6 0 9 3 8 10Zm0-5c0-6 4-8 9-8 0 6-4 9-9 8Z',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',plan:'M7 4H4v18h16V4h-3M8 2h8v5H8ZM8 12h8M8 17h5',chart:'M4 3v18h18M7 16l4-5 4 2 6-8',book:'M12 5v16M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Z',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6ZM8 11l3 3 5-5',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM3 21v-2a9 9 0 0 1 18 0v2',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',close:'m5 5 14 14M19 5 5 19',edit:'m14 4 6 6M4 20l5-1L21 7l-5-5L4 14Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v6l4 2',file:'M14 2H5v20h14V7ZM14 2v6h5M8 13h8M8 17h8'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const btn=(label,action,cls='',ico='')=>`<button class="${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${esc(label)}</span>`;
const field=(label,name,value='',type='text',help='')=>`<div class="field"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}">`}${help?`<small class="help">${help}</small>`:''}</div>`;
const select=(label,name,options,value)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(x=>{let v=typeof x==='string'?x:x.value,l=typeof x==='string'?x:x.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`;
let state,storageOK=true,view='home',catalogTab='bausteine',area='',query='',focusObs=null;
const selectedTemplates=new Set();
function blank(code='Neuer Förderplan'){return {id:uid(),code,grade:'',start:today(),end:'',strengths:'',voice:'',family:'',context:'',externalSupport:'',obs:[],goals:[],logs:[],report:'',reportStamp:'',reportReviewed:false,demo:false}}
function demo(){let p=blank('L-024');p.demo=true;p.grade='6';p.start='2026-11-09';p.end='2027-01-08';p.strengths='Arbeitet gern mit Material und erklärt eigene Ideen im Einzelgespräch. Nimmt konkrete Rückmeldung an.';p.voice='„Mit einer Karte weiß ich besser, was zuerst kommt.“ (fiktives Beispiel)';p.context='Fiktiver Übungsfall · diagnostizierter Förderschwerpunkt Lernen';p.obs=[{id:uid(),date:'2026-11-09',area:AREAS[2],text:'Beginnt in vier von fünf Einzelarbeitsphasen erst nach zwei persönlichen Aufforderungen. Mit sichtbarem ersten Schritt startet die Bearbeitung nach etwa einer Minute.',context:'Mathematik, Einzelarbeit, fünf Beobachtungen',baseline:'1 von 5 Arbeitsphasen innerhalb von zwei Minuten begonnen; ohne Startkarte.',resource:'Beginnt mit einer sichtbaren Schrittkarte zügig.'},{id:uid(),date:'2026-11-10',area:AREAS[1],text:'Löst 3 von 10 Subtraktionsaufgaben bis 20 richtig. Zählt rückwärts und verliert bei Zehnerübergängen den Ausgangspunkt.',context:'Einzelsituation, Aufgabenblatt mit zehn Aufgaben',baseline:'3 von 10 Aufgaben richtig, zählend, ohne Material.',resource:'Kann Mengen bis 10 strukturiert legen.'}];let t=TEMPLATES.find(x=>x.id==='start');p.goals=[{id:uid(),obsId:p.obs[0].id,templateId:t.id,area:t.area,title:t.title,text:t.goal,baseline:p.obs[0].baseline,measures:t.measures,materials:t.materials,source:t.source,material:t.material,frequency:'Täglich in einer Einzelarbeitsphase; 2 Minuten Vorbereitung.',owner:'Klassenleitung (Beispiel)',due:p.end,criterion:'Beginn innerhalb von zwei Minuten in mindestens 4 von 5 Phasen; mit Startkarte, ohne persönliche Aufforderung.',status:'In Arbeit'}];return p}
try{state=JSON.parse(localStorage.getItem('foerderatelier-v1')||'null')}catch(e){storageOK=false}
if(!state||!Array.isArray(state.plans)){let p=demo();state={version:1,active:p.id,plans:[p]}}
const plan=()=>state.plans.find(p=>p.id===state.active)||state.plans[0];
function save(invalidate=true){if(invalidate&&plan())plan().reportReviewed=false;try{localStorage.setItem('foerderatelier-v1',JSON.stringify(state));storageOK=true}catch(e){storageOK=false;toast('Speichern im Browser nicht möglich. Bitte Daten sichern.')}let s=$('#saved');if(s)s.textContent=storageOK?'Im Browser gespeichert':'Nicht gespeichert – bitte sichern'}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function go(v){view=v;render();window.scrollTo(0,0)}
const navs=[['home','Übersicht','home'],['obs','Beobachtungen','eye'],['plan','Förderplan','plan'],['report','Verlauf & Bericht','chart'],['catalog','Bausteindatenbank','book']];
function render(){const p=plan();$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${icon('leaf')}<div><strong>Bausteine zur Förderplanung</strong><small>FÖRDERSCHWERPUNKT LERNEN</small></div></div><div class="nav-label">Mein Arbeitsbereich</div><nav class="nav" aria-label="Hauptnavigation">${navs.map(([id,l,i])=>btn(l,'nav:'+id,view===id?'active':'',i)).join('')}</nav><div class="sidebar-bottom">${icon('shield')}<p>Raum für Entwicklung.<br>Mit Blick auf das einzelne Kind.</p>${btn('Daten & Sicherung','settings','ghost small','download')}<div class="account"><span class="avatar">JB</span><div>Meine Förderplanung<br><small style="color:#b2c9bd">Privater Arbeitsbereich</small></div></div></div></aside><div><header class="topbar"><div class="breadcrumb">Mein Arbeitsbereich <b>/ ${navs.find(x=>x[0]===view)[1]}</b></div><div class="flex"><span class="save-state">${icon('shield')}<span id="saved">${storageOK?'Nur in diesem Browser':'Speichern nicht verfügbar'}</span></span>${btn('Neuer Förderplan','new','small','plus')}${btn('Daten','settings','small mobiledata','download')}</div></header><main class="main" id="main">${view==='home'?home():view==='obs'?observations():view==='plan'?planning():view==='report'?reportView():catalog()}</main></div></div>`;if(view==='catalog'&&catalogTab==='bausteine')renderCards()}
function head(kicker,title,desc,action=''){return `<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</div>`}
function picker(){let p=plan();return `<label for="plan-select" class="help">Aktueller Förderplan</label><select class="plan-picker" id="plan-select">${state.plans.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.code)}${x.grade?' · Klasse '+esc(x.grade):''}${x.demo?' · Demofall':''}</option>`).join('')}</select>`}
function readiness(){let p=plan();return [{label:'Ausgangslage dokumentiert',ok:p.obs.length>0&&p.obs.every(o=>o.text.trim()&&o.context.trim())},{label:'Förderziele formuliert',ok:p.goals.length>0&&p.goals.every(g=>g.text.trim()&&g.due)},{label:'Verlauf zu jedem Ziel erfasst',ok:p.goals.length>0&&p.goals.every(g=>p.logs.some(l=>l.goalId===g.id))},{label:'Zielerreichung eingeschätzt',ok:p.goals.length>0&&p.goals.every(g=>p.logs.some(l=>l.goalId===g.id&&l.judgement!=='Noch offen'))}]}
function home(){let p=plan(),r=readiness(),n=r.filter(x=>x.ok).length;return `<div class="hero"><div><div class="eyebrow">Individuell planen. Gemeinsam begleiten.</div><h1>Kleine Schritte.<br>Sichtbare Entwicklung.</h1><p>Von einer konkreten Beobachtung zu einer Förderung, die im Unterricht ankommt.</p><div class="flex">${btn('Verhaltensweisen auswählen','browse','primary','plus')}${btn('Förderplan öffnen','nav:plan','','plan')}</div></div><div class="growth"><svg viewBox="0 0 180 170"><path d="M90 150V65M90 107C45 108 40 81 40 65c32-1 51 17 50 42ZM90 84c1-35 21-54 49-54 0 32-19 51-49 54ZM90 136c-24-5-37-18-39-37M90 117c28 0 44-15 49-37M60 154h61"/><path d="m48 75 42 32m39-66-39 43"/></svg></div></div><div class="stats"><div class="stat"><div class="circle-icon">${icon('eye')}</div><div class="num">${p.obs.length}</div><small>Beobachtungen<br>festgehalten</small></div><div class="stat"><div class="circle-icon">${icon('plan')}</div><div class="num">${p.goals.length}</div><small>Förderziele<br>im Fokus</small></div><div class="stat"><div class="circle-icon">${icon('chart')}</div><div class="num">${p.logs.length}</div><small>Verlaufseinträge<br>dokumentiert</small></div></div><div class="grid"><div><section class="panel"><div class="panelhead"><h2>Im Blick: ${esc(p.code)}</h2>${p.demo?badge('Fiktiver Demofall','amber'):badge('Individuelle Planung')}</div>${picker()}<div class="student"><div class="student-icon">${icon('user')}</div><div><h3>${esc(p.code)}</h3><div class="sub">${p.grade?'Klasse '+esc(p.grade)+' · ':''}Förderschwerpunkt Lernen</div></div></div><div class="info-grid"><div><small>Förderzeitraum</small><strong>${date(p.start)} – ${date(p.end)}</strong></div><div><small>Fokus</small><strong>${[...new Set(p.goals.map(x=>x.area))].map(esc).join(', ')||'Noch nicht festgelegt'}</strong></div></div><div class="hint"><strong>Das gelingt bereits</strong><br>${esc(p.strengths)||'Stärken, Interessen und hilfreiche Bedingungen ergänzen.'}</div><div class="row"><span class="sub">Wenige Ziele. Verbindliche Schritte.</span>${btn('Rahmen bearbeiten','profile','small','edit')}</div><div class="steps"><div class="step ${p.obs.length?'done':''}">Beobachten</div><div class="step ${p.goals.length?'done':''}">Planen</div><div class="step ${p.logs.length?'done':''}">Überprüfen</div><div class="step ${p.reportReviewed?'done':''}">Berichten</div></div></section><section class="panel"><div class="panelhead"><h2>Aktuelle Beobachtungen</h2>${btn('Alle ansehen','nav:obs','ghost small')}</div>${p.obs.slice(-2).reverse().map(obsCard).join('')||'<div class="empty">Mit einer konkreten Beobachtung beginnt die Planung.</div>'}</section></div><div class="side-panels"><section class="panel"><div class="panelhead"><h2>Der nächste Schritt</h2>${icon('leaf')}</div><p class="quote">„Was tut das Kind – und unter welchen Bedingungen gelingt es?“</p><p class="sub">Beschreibe eine Situation, die du gesehen oder gehört hast. Halte auch Unterstützung und Häufigkeit fest.</p>${btn(p.obs.length?'Passende Ziele finden':'Beobachtung hinzufügen',p.obs.length?'suggest:'+p.obs[0].id:'addobs','primary small')}</section><section class="panel"><div class="panelhead"><h2>Bereit für den Bericht?</h2></div><div class="row"><span class="sub">Dokumentationsgrundlage</span><strong>${n} / 4</strong></div><div class="progress-track"><span style="width:${n*25}%"></span></div><div class="checklist">${r.map(x=>`<div>${icon(x.ok?'check':'clock')}<span>${x.label}</span></div>`).join('')}</div>${btn('Verlauf & Bericht öffnen','nav:report','small')}</section></div></div><div class="footer-note">Arbeitsgrundlage: dein Auswahlkatalog zur Förderplanung · Vorschläge bleiben pädagogische Entscheidungen · Recherche: 19.11.2026</div>`}
function obsCard(o){let linked=plan().goals.some(g=>g.obsId===o.id);return `<article class="observation"><div class="row">${badge(o.area)}<span class="meta">${date(o.date)}</span></div><p>${esc(o.text)}</p><div class="meta">${esc(o.context)}</div><div class="row" style="margin-top:14px">${btn(linked?'Weiteres Ziel ableiten':'Ziel ableiten','suggest:'+o.id,'small','leaf')}${btn('Bearbeiten','editobs:'+o.id,'ghost small','edit')}</div></article>`}
function observations(){let p=plan();return head('Wahrnehmen & verstehen','Beobachtungen','Konkretes Handeln ist der Ausgangspunkt deiner Planung.',btn('Beobachtung ergänzen','addobs','primary','plus'))+picker()+`<div class="grid"><section class="panel"><h2>Was ist zu beobachten?</h2><p class="sub">Situation · Handlung · Häufigkeit · Unterstützung</p>${p.obs.map(obsCard).join('')||'<div class="empty">Noch keine Beobachtungen. Ergänze eine Situation aus dem Unterricht.</div>'}</section><aside><section class="panel"><h2>Beschreiben statt bewerten</h2><p class="sub">Statt „ist unmotiviert“:</p><p class="quote">„Beginnt in vier von fünf Arbeitsphasen erst nach zwei persönlichen Aufforderungen.“</p><div class="hint">Ergänze: Wann gelingt es? Wie ist die Aufgabe gestaltet? Welche Hilfe wurde gegeben?</div><p class="sub">Eine einzelne Beobachtung begründet noch kein dauerhaftes Verhaltensmuster. Prüfe mehrere Situationen.</p></section></aside></div>`}
function planning(){let p=plan();return head('Ziele & Unterstützung','Der Förderplan','Beobachtbar, erreichbar und gemeinsam vereinbart.',btn('Eigenes Ziel ergänzen','customgoal','primary','plus'))+picker()+`<div class="flex" style="margin-bottom:20px">${badge(p.goals.length+' Ziele im Fokus')}${btn('Mehrere Bausteine auswählen','browse','small','plus')}${btn('Tabellarisches PDF herunterladen','pdfplan','primary small','download')}${btn('Tabellenvorschau','tablepreview','small','eye')}${btn('Tabelle drucken','printplan','small')}${btn('Für Word / Pages (.rtf)','rtfplan','small','file')}</div>${p.goals.length>3?'<div class="hint warning">Dein Katalog empfiehlt in der Regel zwei bis drei priorisierte Ziele pro Zeitraum. Prüfe die Umsetzbarkeit dieser Auswahl.</div>':''}${p.goals.map(goalCard).join('')||`<div class="panel empty"><h2>Ein nächster Schritt reicht für den Anfang.</h2><p>Leite ein Ziel aus einer dokumentierten Beobachtung ab.</p>${btn('Zu den Beobachtungen','nav:obs','primary')}</div>`}<div class="hint">Quoten, Hilfen und Zeiträume in den Vorschlägen sind veränderbare Beispiele. Die Maßnahmen beschreiben das Handeln der Lehrkraft; Material allein ist noch keine Maßnahme.</div>`}
function goalCard(g){let p=plan(),o=p.obs.find(x=>x.id===g.obsId),s=SOURCES[g.source]||SOURCES.praxis;return `<article class="goal"><div class="row"><div class="flex">${badge(g.area)}${badge(g.status,'gray')}</div>${btn('Bearbeiten','editgoal:'+g.id,'ghost small','edit')}</div><h2 style="margin-top:18px">${esc(g.title)}</h2><p>${esc(g.text)}</p><div class="sub">Überprüfung: ${date(g.due)} · ${esc(g.owner)||'Zuständigkeit offen'}</div><div class="goal-details"><div><h3>Beobachtete Ausgangslage</h3><p>${esc(o?.text||'Keine verknüpfte Beobachtung')}</p><p class="sub">Ausgangswert: ${esc(g.baseline)||'offen'}</p></div><div><h3>Maßnahmen & Häufigkeit</h3><p>${esc(g.measures)}</p><p class="sub">${esc(g.frequency)||'Häufigkeit noch festlegen.'}</p></div><div><h3>Materialien & Hilfen</h3><p>${esc(g.materials)}</p>${g.material?btn('Vorlage ansehen','material:'+g.material,'small','file'):''}</div></div><hr class="sep"><div class="row"><span class="sub">Grundlage: ${esc(s.short)}${g.catalogPage?' · S. '+g.catalogPage:''}</span><div class="flex">${btn('Quellenhinweis','source:'+g.source,'ghost small')}${btn('Verlauf ergänzen','log:'+g.id,'small','plus')}</div></div></article>`}
function reportView(){let p=plan(),checks=readiness(),complete=checks.every(c=>c.ok),stale=p.reportStamp&&p.reportStamp!==stamp();return head('Dokumentieren & reflektieren','Entwicklung sichtbar machen','Der Bericht beschreibt belegte Veränderungen und offene Fragen.')+picker()+`<div class="grid"><div><section class="panel"><div class="panelhead"><h2>Förderverlauf</h2>${btn('Eintrag ergänzen','log:','small','plus')}</div><p class="sub">Dokumentiere, was tatsächlich durchgeführt wurde und unter welchen Bedingungen ein Ergebnis entstand.</p>${p.logs.length?`<div class="timeline">${[...p.logs].sort((a,b)=>b.date.localeCompare(a.date)).map(l=>{let g=p.goals.find(g=>g.id===l.goalId);return `<article class="entry"><time>${date(l.date)} · ${esc(l.author)}</time><h3 style="margin-top:7px">${esc(g?.title||'Ziel nicht mehr vorhanden')}</h3>${badge(l.judgement,l.judgement==='Noch offen'?'gray':'')}<p>${esc(l.result)}</p><p class="sub">Hilfen / Bedingungen: ${esc(l.support)}</p>${btn('Bearbeiten','editlog:'+l.id,'ghost small','edit')}</article>`}).join('')}</div>`:'<div class="empty">Noch kein Verlauf erfasst. Aus einem geplanten Ziel lässt sich keine Zielerreichung ableiten.</div>'}</section><section class="panel"><div class="panelhead"><h2>Entwicklungsbericht</h2>${badge(p.reportReviewed&&!stale?'Fachlich geprüft':'Entwurf','amber')}</div><p class="sub">Regelbasierter Textentwurf aus deinen Einträgen. Er trifft keine Diagnose und behauptet keine Wirkung der Förderung.</p>${!complete?'<div class="hint warning">Die Datengrundlage ist noch unvollständig. Fehlende Beobachtungen, Ziele oder Verlaufsnachweise werden im Entwurf benannt.</div>':''}${stale?'<div class="hint warning">Die zugrunde liegenden Daten wurden geändert. Bitte den Entwurf neu ableiten und danach fachlich prüfen.</div>':''}<div class="flex" style="margin:15px 0">${btn(p.report?'Entwurf neu ableiten':'Berichtsentwurf erstellen','generate','primary','file')}${p.report?btn('Drucken / PDF','printreport','small','download'):''}${p.report?btn('Word / Pages (.rtf)','rtfreport','small'):''}</div>${p.report?`<label for="report-text">Bericht bearbeiten</label><textarea class="report" id="report-text">${esc(p.report)}</textarea><label style="margin-top:15px;font-weight:400"><input type="checkbox" id="reviewed" ${p.reportReviewed&&!stale?'checked':''}>Ich habe Aussagen, Belege und Schlussfolgerungen fachlich geprüft.</label>`:''}</section></div><aside><section class="panel"><h2>Was ist ableitbar?</h2><div class="checklist">${checks.map(x=>`<div>${icon(x.ok?'check':'clock')}${x.label}</div>`).join('')}</div><div class="hint">Dokumentierte Ausgangslage, umgesetzte Maßnahmen, Verlauf, Einschätzung und nächste Schritte können zu einem Entwurf verbunden werden.</div><p class="sub">Ein Förderplan allein trägt keinen Entwicklungsbericht. Auch eine einzelne bessere Leistung belegt weder Stabilität noch Transfer oder eine ursächliche Förderwirkung.</p><p class="sub">Die Überprüfung des Förderbedarfs, amtliche Entscheidungen und die pädagogische Gesamtbewertung bleiben eigenständige fachliche Aufgaben.</p></section><section class="panel"><h2>Beteiligung festhalten</h2><p class="sub">Perspektiven des Kindes und der Erziehungsberechtigten werden im Bericht getrennt ausgewiesen.</p>${btn('Perspektiven ergänzen','profile','small','edit')}</section></aside></div>`}
function legacyCatalog(){return head('Fachlich begründet auswählen','Bausteine & Quellen','Dein Auswahlkatalog, ergänzt um nachvollziehbare Forschungsgrundlagen.')+`<div class="tabs">${[['bausteine','Förderbausteine'],['material','Materialvorlagen'],['quellen','Literatur & Evidenz']].map(([id,l])=>btn(l,'tab:'+id,catalogTab===id?'active':'')).join('')}</div>${catalogTab==='bausteine'?`<div class="hint">${focusObs?'Vorschläge zur ausgewählten Beobachtung: Auswahl nach Förderbereich und Wortübereinstimmungen. Bitte fachlich auf Passung prüfen.':'74 Bausteine aus deinem aktualisierten Katalog. Keine automatische Diagnostik oder KI-Analyse.'}</div><label for="search" class="help">Bausteine durchsuchen</label><input id="search" class="search" type="search" placeholder="Zum Beispiel: Lesen, Arbeitsbeginn, Zahlbeziehungen …" value="${esc(query)}"><div class="filters">${['Alle',...AREAS].map(x=>btn(x,'filter:'+x,area===x?'selected':'')).join('')}</div><div class="sub" id="count" style="margin-bottom:16px"></div><div class="catalog-grid" id="cards"></div>`:catalogTab==='material'?`<div class="hint">Eigene, bearbeitbare Umsetzungshilfen – keine evaluierten Trainingsprogramme. Die Evidenz bezieht sich auf den zugeordneten Förderansatz, nicht auf diese einzelnen Vorlagen. Forschungsleitfäden mit weiteren Beispielen findest du unter „Literatur & Evidenz“.</div><div class="catalog-grid">${Object.entries(MATERIALS).map(([id,m])=>`<article class="catalog-card">${badge('Eigene Vorlage','gray')}<h3>${m.title}</h3><p>Vor dem Einsatz an Lernstand, Alter und Ziel anpassen. Bearbeitbar und druckbar.</p>${btn('Vorlage öffnen','material:'+id,'small','file')}</article>`).join('')}</div>`:`<section class="panel"><h2>So sind die Quellen einzuordnen</h2><p>Verwendet werden wissenschaftliche Publikationen im DIPF-Repositorium peDOCS und Forschungsleitfäden des staatlichen Institute of Education Sciences. Keine kommerziellen Materialportale, Blogs oder Anbieterempfehlungen.</p><p class="sub">Die Auswahl ist eine gezielte Recherche, kein systematisches Review. Kein hier aufgeführter Beleg validiert die gesamte Anwendung für den deutschen Förderschwerpunkt Lernen. Recherchestand: 19.11.2026.</p>${Object.entries(SOURCES).map(([id,s])=>sourceHTML(id,s)).join('')}</section>`}`}
function score(t){let o=plan().obs.find(x=>x.id===focusObs);if(!o)return 0;let words=(o.text+' '+o.context).toLowerCase().split(/[^a-zäöüß]+/).filter(x=>x.length>4);return words.reduce((n,w)=>n+(t.title+' '+t.observation).toLowerCase().includes(w),0)}
function legacyRenderCards(){let list=TEMPLATES.filter(t=>(area==='Alle'||t.area===area)&&[t.title,t.observation,t.goal,t.materials].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>score(b)-score(a));$('#count').textContent=list.length+' passende Bausteine';$('#cards').innerHTML=list.map(t=>`<article class="catalog-card">${badge(t.area)}<h3>${esc(t.title)}</h3><p class="muted">${esc(t.observation)}</p><p><strong>Möglicher nächster Schritt</strong><br>${esc(t.goal)}</p><span class="help">${t.source==='praxis'?'Individuell zu erproben':'Forschungsbezug · Übertragbarkeit prüfen'} · ${esc(SOURCES[t.source].short)}</span><div class="actions flex">${btn('Ansehen & anpassen','template:'+t.id,'small','plus')}${btn('Evidenz','source:'+t.source,'ghost small')}</div></article>`).join('')||'<div class="empty">Keine Treffer. Wähle einen anderen Bereich oder Suchbegriff.</div>'}
function sourceHTML(id,s){return `<article class="source"><h3>${esc(s.title)}</h3><p class="sub">${esc(s.author)}</p><p><strong>Beleg:</strong> ${esc(s.evidence)}</p><p><strong>Untersuchungskontext:</strong> ${esc(s.population)}</p><p class="sub"><strong>Grenze:</strong> ${esc(s.limit)}</p>${s.url?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">Publikation und Materialien öffnen</a>`:''}</article>`}
function openModal(title,html,onSubmit){let d=$('#modal');d.innerHTML=`<div class="dialoghead"><h2>${title}</h2>${btn('Schließen','close','dialog-close','close')}</div><form id="dialogform" class="dialogbody">${html}</form>`;d.querySelector('[data-action=close]').setAttribute('aria-label','Dialog schließen');d.querySelectorAll('button').forEach(b=>{if(b.dataset.action)b.type='button'});$('#dialogform').onsubmit=e=>{e.preventDefault();if(onSubmit)onSubmit(Object.fromEntries(new FormData(e.target)))};d.showModal()}
const footer=(label='Speichern')=>`<div class="dialogfooter">${btn('Abbrechen','close')}<button class="primary" type="submit">${label}</button></div>`;
function closeDialog(){ $('#modal').close();$('#modal').classList.remove('wide-dialog') }
function obsForm(id){let p=plan(),o=p.obs.find(x=>x.id===id)||{date:today(),area:AREAS[2]};openModal(id?'Beobachtung bearbeiten':'Beobachtung festhalten',`<p class="sub">Beobachtbares Handeln, keine Eigenschaften oder Diagnosevermutungen.</p><div class="form-grid">${field('Datum','date',o.date,'date')}${select('Förderbereich','area',AREAS,o.area)}</div>${field('Was tut oder sagt die Schülerin / der Schüler? *','text',o.text,'textarea','So konkret, dass eine zweite Person dieselbe Handlung beobachten könnte.')}${field('Situation und Beobachtungsumfang *','context',o.context,'text','Fach, Aufgabe, Sozialform, Dauer und Anzahl der Situationen.')}${field('Ausgangswert / aktueller Stand','baseline',o.baseline,'text','Zum Beispiel 3 von 10 Aufgaben; mit Material; am 19.11.')}${field('Was gelingt? Welche Bedingungen helfen?','resource',o.resource,'textarea')}${id?btn('Beobachtung löschen','deleteobs:'+id,'danger small'):''}${footer()}`,v=>{if(!v.date||!v.text.trim()||!v.context.trim())return toast('Bitte Datum, Handlung und Situation ergänzen.');let x={...o,...v,id:id||uid()};if(id)p.obs[p.obs.findIndex(x=>x.id===id)]=x;else p.obs.push(x);save();closeDialog();render();toast('Beobachtung gespeichert.')})}
function profileForm(isNew=false){let p=isNew?blank():plan();openModal(isNew?'Neuen Förderplan anlegen':'Rahmen & Perspektiven',`<div class="hint">Für Schülerinnen und Schüler mit bereits diagnostiziertem FSP Lernen. Verwende ein Kürzel statt Klarnamen. Eingaben werden lokal in diesem Browser gespeichert.</div><div class="form-grid">${field('Schülerkürzel *','code',isNew?'':p.code,'text')}${field('Klassenstufe','grade',p.grade)}${field('Beginn *','start',p.start,'date')}${field('Überprüfung / Ende','end',p.end,'date')}</div>${field('Stärken, Interessen, gelingende Bedingungen','strengths',p.strengths,'textarea')}${field('Schulischer Kontext','context',p.context,'textarea','Zum Beispiel: Besonderheiten der Schullaufbahn.')}${field('Perspektive des Kindes','voice',p.voice,'textarea','Wörtliche Aussage oder kenntlich gemachte Zusammenfassung; Datum ergänzen.')}${field('Familiärer Kontext','family',p.family,'textarea','Zum Beispiel: getrennt lebende Eltern, Anzahl der Geschwister, Wohnsituation.')}${field('Bestehende außerschulische Förderung','externalSupport',p.externalSupport,'textarea','Zum Beispiel: Logopädie, Ergotherapie, Psychotherapie.')}${footer(isNew?'Förderplan anlegen':'Speichern')}`,v=>{if(!v.code.trim()||!v.start)return toast('Bitte Kürzel und Beginn ergänzen.');if(v.end&&v.end<v.start)return toast('Das Ende muss am oder nach dem Beginn liegen.');Object.assign(p,v);if(isNew){state.plans.push(p);state.active=p.id;focusObs=null;selectedTemplates.clear()}save();closeDialog();go('home');toast(isNew?'Neuer Förderplan angelegt.':'Rahmen gespeichert.')})}
function goalForm(id,tid){let p=plan(),g=p.goals.find(x=>x.id===id),t=TEMPLATES.find(x=>x.id===tid);if(!p.obs.length){toast('Bitte zuerst eine Beobachtung festhalten.');return obsForm()}let o=p.obs.find(x=>x.id===(g?.obsId||focusObs))||p.obs[0];g=g||{id:uid(),obsId:o.id,area:t?.area||o.area,title:t?.title||'',text:t?.goal||'',baseline:o.baseline||'',measures:t?.measures||'',materials:t?.materials||'',source:t?.source||'praxis',research:t?.research||'',catalogPage:t?.catalogPage||null,material:t?.material||'',templateId:t?.id||'',due:p.end||'',criterion:'',owner:'',frequency:'',status:'In Arbeit'};openModal(id?'Förderziel bearbeiten':'Förderziel anpassen',`<div class="hint">Ein Vorschlag wird erst durch deine Anpassung zum individuellen Ziel. Zielquoten sind Beispiele, keine Normwerte.</div>${select('Bezug zur Beobachtung *','obsId',p.obs.map(x=>({value:x.id,label:date(x.date)+' · '+x.text.slice(0,90)})),g.obsId)}<div class="form-grid">${field('Kurztitel *','title',g.title)}${select('Förderbereich','area',AREAS,g.area)}</div>${field('Förderziel: Handlung + Bedingung + Erfolgskriterium *','text',g.text,'textarea')}${field('Ausgangswert / Stand','baseline',g.baseline,'textarea')}${field('Maßnahmen: Was tun die begleitenden Personen? *','measures',g.measures,'textarea')}${field('Materialien / Hilfen – frei ergänzbar','materials',g.materials,'textarea')}<div class="form-grid">${field('Häufigkeit und Dauer *','frequency',g.frequency)}${field('Verantwortliche Person / Rolle *','owner',g.owner)}${field('Überprüfung am *','due',g.due,'date')}${select('Planungsstand','status',['In Arbeit','Fortführen','Anpassen','Abgeschlossen'],g.status)}</div><small class="help">Grundlage: ${esc(SOURCES[g.source].short)}. Veränderte Maßnahmen müssen erneut auf Quellenpassung geprüft werden.</small>${id?btn('Ziel löschen','deletegoal:'+id,'danger small'):''}${footer('In den Förderplan übernehmen')}`,v=>{if(['title','text','measures','frequency','owner','due'].some(k=>!v[k]?.trim()))return toast('Bitte alle mit * markierten Angaben ergänzen.');if(v.due<p.start)return toast('Die Überprüfung liegt vor dem Förderbeginn.');Object.assign(g,v);if(id)p.goals[p.goals.findIndex(x=>x.id===id)]=g;else p.goals.push(g);save();closeDialog();go('plan');toast('Förderziel übernommen.')})}
function logForm(goalId,id){let p=plan();if(!p.goals.length)return toast('Bitte zuerst ein Förderziel anlegen.');let l=p.logs.find(x=>x.id===id)||{goalId:goalId||p.goals[0].id,date:today(),judgement:'Noch offen'};openModal('Förderverlauf dokumentieren',`${select('Zugehöriges Förderziel','goalId',p.goals.map(g=>({value:g.id,label:g.title})),l.goalId)}<div class="form-grid">${field('Datum *','date',l.date,'date')}${field('Dokumentiert durch *','author',l.author)}</div>${field('Tatsächlich durchgeführte Förderung *','delivered',l.delivered,'textarea','Art, Häufigkeit und Dauer; auch Ausfälle oder Änderungen festhalten.')}${field('Ergebnis / beobachtetes Handeln *','result',l.result,'textarea','Konkreter Wert oder Handlung; Umfang und Aufgabenanforderung benennen.')}${field('Hilfen und Bedingungen *','support',l.support,'textarea','Zum Beispiel selbstständig, mit Startkarte; Einzel- oder Gruppensituation.')}${field('Nachweis / Fundstelle','evidence',l.evidence,'text','Zum Beispiel Arbeitsprobe vom …, Beobachtungsbogen Nr. …; kein Dateiupload.')}${select('Fachliche Einschätzung der Zielerreichung','judgement',['Noch offen','Noch nicht erreicht','Teilweise erreicht','Erreicht','Unter diesen Bedingungen nicht beurteilbar'],l.judgement)}${field('Begründung und nächster Schritt','next',l.next,'textarea','Vergleichbarkeit, Grenzen, Transfer und Anpassung beschreiben.')}${id?btn('Eintrag löschen','deletelog:'+id,'danger small'):''}${footer()}`,v=>{if(['date','author','delivered','result','support'].some(k=>!v[k]?.trim()))return toast('Bitte alle mit * markierten Angaben ergänzen.');if(v.judgement!=='Noch offen'&&!v.next.trim())return toast('Bitte die Einschätzung begründen und den nächsten Schritt festhalten.');let x={...l,...v,id:id||uid()};if(id)p.logs[p.logs.findIndex(x=>x.id===id)]=x;else p.logs.push(x);save();closeDialog();go('report');toast('Verlaufseintrag gespeichert.')})}
function stamp(){let p=plan();return JSON.stringify([p.code,p.grade,p.start,p.end,p.strengths,p.context,p.voice,p.family,p.externalSupport||'',p.obs,p.goals,p.logs])}
function reportText(){let p=plan(),parts=[`ENTWICKLUNGSBERICHT – ENTWURF${p.demo?' · FIKTIVER DEMOFALL':''}`,`Schülerkürzel: ${p.code}\nKlasse: ${p.grade||'nicht angegeben'}\nFörderschwerpunkt: Lernen (als diagnostiziert vorausgesetzt)\nZeitraum: ${date(p.start)} bis ${date(p.end)}\nErstellt am: ${date(today())}`,`SCHULISCHER KONTEXT\n${p.context||'Nicht dokumentiert.'}`,`STÄRKEN UND RESSOURCEN\n${p.strengths||'Nicht dokumentiert.'}`,`PERSPEKTIVE DES KINDES\n${p.voice||'Nicht dokumentiert.'}`,`FAMILIÄRER KONTEXT\n${p.family||'Nicht dokumentiert.'}`,`BESTEHENDE AUSSERSCHULISCHE FÖRDERUNG\n${p.externalSupport||'Nicht dokumentiert.'}`];if(!p.goals.length)parts.push('Es wurden noch keine Förderziele dokumentiert. Eine zielbezogene Entwicklung kann nicht abgeleitet werden.');p.goals.forEach((g,i)=>{let o=p.obs.find(x=>x.id===g.obsId),ls=p.logs.filter(x=>x.goalId===g.id).sort((a,b)=>a.date.localeCompare(b.date));parts.push(`FÖRDERSCHWERPUNKT ${i+1}: ${g.title}\nBereich: ${g.area}\nAusgangslage${o?.date?' vom '+date(o.date):''}: ${o?.text||'Nicht dokumentiert.'}\nSituation: ${o?.context||'Nicht dokumentiert.'}\nGelingende Bedingungen: ${o?.resource||'Nicht dokumentiert.'}${g.baseline?'\nBisher dokumentierter Ausgangswert: '+g.baseline:''}\nVereinbartes Ziel: ${g.text}\nÜberprüfung vorgesehen: ${date(g.due)}\nGeplante Maßnahmen: ${g.measures}\nGeplanter Umfang: ${g.frequency||'Nicht dokumentiert.'}\nZuständigkeit: ${g.owner||'Nicht dokumentiert.'}\nVorgesehene Materialien: ${g.materials||'Nicht dokumentiert.'}`);if(!ls.length)parts.push('VERLAUF UND ZIELERREICHUNG\nZu diesem Ziel liegen keine Verlaufseinträge vor. Umsetzung und Zielerreichung sind nicht beurteilbar.');else{parts.push('DOKUMENTIERTER VERLAUF\n'+ls.map(l=>`${date(l.date)} – dokumentiert durch ${l.author}:\nDurchführung: ${l.delivered}\nErgebnis: ${l.result}\nHilfen / Bedingungen: ${l.support}\nNachweis: ${l.evidence||'Keine Fundstelle angegeben.'}\nEinschätzung der dokumentierenden Person: ${l.judgement}\nBegründung / nächster Schritt: ${l.next||'Noch zu ergänzen.'}`).join('\n\n'));if(ls.length===1)parts.push('Ein einzelner Verlaufseintrag erlaubt keine Aussage über einen stabilen Entwicklungstrend.');if(ls.every(l=>l.judgement==='Noch offen'))parts.push('Eine fachliche Einschätzung der Zielerreichung steht noch aus.')}parts.push(`Weiteres Vorgehen laut Förderplan: ${g.status}.`) });let unlinked=p.obs.filter(o=>!p.goals.some(g=>g.obsId===o.id));if(unlinked.length)parts.push('WEITERE BEOBACHTUNGEN OHNE ABGELEITETES ZIEL\n'+unlinked.map(o=>`${date(o.date)}: ${o.text}`).join('\n'));parts.push('GESAMTEINSCHÄTZUNG UND VEREINBARUNGEN\n[Durch die verantwortliche Lehrkraft ergänzen: belegte Veränderungen, verbleibender Bedarf, Beteiligung, nächste Überprüfung.]','GRENZEN DER ABLEITUNG\nDieser Entwurf gibt dokumentierte Angaben wieder. Vergleichbarkeit, Stabilität und Transfer sind fachlich zu prüfen. Eine ursächliche Wirkung der Förderung oder Änderung des Förderstatus wird nicht automatisch abgeleitet.');return parts.join('\n\n')}
function planText(){let p=plan();return [`FÖRDERPLAN${p.demo?' · FIKTIVER DEMOFALL':''}`,`${p.code} · Klasse ${p.grade||'offen'} · FSP Lernen\nZeitraum: ${date(p.start)} bis ${date(p.end)}`,`Stärken: ${p.strengths||'offen'}\nSchulischer Kontext: ${p.context||'offen'}\nPerspektive Kind: ${p.voice||'offen'}\nFamiliärer Kontext: ${p.family||'offen'}\nBestehende außerschulische Förderung: ${p.externalSupport||'offen'}`,...p.goals.map((g,i)=>{let o=p.obs.find(o=>o.id===g.obsId);return `ZIEL ${i+1}: ${g.title} · ${g.area}\nBeobachtung: ${o?.text||'offen'}${g.baseline?'\nBisher dokumentierter Ausgangswert: '+g.baseline:''}\nZiel: ${g.text}\nMaßnahmen: ${g.measures}\nUmfang: ${g.frequency}\nMaterial: ${g.materials}\nVerantwortlich: ${g.owner}\nTermin: ${date(g.due)}\nStand: ${g.status}\nGrundlage: ${SOURCES[g.source]?.title||'Eigener Baustein'}${SOURCES[g.source]?.url?' · '+SOURCES[g.source].url:''}`})].join('\n\n')}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function rtf(s){let t='';for(let c of s){let n=c.charCodeAt(0);t+=c==='\n'?'\\par\n':/[\\{}]/.test(c)?'\\'+c:n>127?'\\u'+(n>32767?n-65536:n)+'?':c}return '{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\f0\\fs28 '+t+'}'}
function printText(s){$('#print').textContent=s;window.print()}
function material(id){let m=MATERIALS[id];openModal(m.title,`<div class="hint">Eigene Umsetzungsvorlage, nicht als einzelnes Material evaluiert. Vor dem Einsatz anpassen.</div><label for="material-text">Vorlage bearbeiten</label><textarea id="material-text" style="min-height:350px">${esc(m.text)}</textarea><div class="dialogfooter">${btn('Drucken / PDF','printmaterial','primary','download')}${btn('Word / Pages (.rtf)','rtfmaterial')}</div>`)}
function settings(){openModal('Daten & Sicherung',`<p>Förderpläne bleiben im lokalen Speicher dieses Browsers. Es gibt keine Synchronisierung, keine serverseitige Schülerdatenbank und keine Übertragung an ein KI-Modell.</p><div class="hint warning">Browserdaten können gelöscht werden. Sichere regelmäßig eine JSON-Datei. Diese ist nicht verschlüsselt; verwende Kürzel und einen schulisch freigegebenen Speicherort. Die App ersetzt keine schulische Datenschutzfreigabe.</div><div class="flex">${btn('Alle Pläne sichern (.json)','backup','primary','download')}${btn('Sicherung importieren','import','','file')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><hr class="sep"><p class="sub">Importierte Pläne werden als zusätzliche Kopien angelegt. Bestehende Pläne bleiben erhalten.</p>${btn('Demofall hinzufügen','adddemo','small')}${plan()?btn('Aktuellen Plan löschen','deleteplan','danger small'):''}<div class="help" style="margin-top:18px">Version 1.3 · ${TEMPLATES.length} Förderbausteine · 7 wissenschaftliche Quellen und dein Auswahlkatalog · 6 Materialvorlagen</div>`)}
function confirmAction(title,message,run){closeDialog();openModal(title,`<p>${message}</p>${footer('Löschen')}`,()=>{run();save();closeDialog();render();toast('Gelöscht.')})}
function validateImport(x){if(x?.version!==1||!Array.isArray(x.plans)||x.plans.length>100||!x.plans.length)throw Error('Ungültiges Format.');const safeId=s=>typeof s==='string'&&/^[a-f0-9-]{36}$/.test(s); const strings=(o,keys)=>keys.every(k=>typeof o[k]==='string'&&o[k].length<100000);for(const p of x.plans){if(!p||!safeId(p.id))throw Error('Ungültige Kennung.');if(!strings(p,['id','code','grade','start','end','strengths','voice','family','context','report'])||!Array.isArray(p.obs)||!Array.isArray(p.goals)||!Array.isArray(p.logs))throw Error('Ungültiger Förderplan.');if(p.externalSupport!==undefined&&!strings(p,['externalSupport']))throw Error('Ungültige außerschulische Förderung.');if(p.obs.length>10000||p.goals.length>1000||p.logs.length>10000)throw Error('Datei enthält zu viele Einträge.');if(new Set(p.obs.map(x=>x.id)).size!==p.obs.length||new Set(p.goals.map(x=>x.id)).size!==p.goals.length)throw Error('Doppelte Kennungen.');for(let o of p.obs)if(!o||!safeId(o.id)||!strings(o,['id','date','area','text','context','baseline','resource'])||!AREAS.includes(o.area))throw Error('Ungültige Beobachtung.');for(let g of p.goals)if(!g||!safeId(g.id)||!strings(g,['id','obsId','area','title','text','baseline','measures','materials','source','material','due','criterion','owner','frequency','status'])||!p.obs.some(o=>o.id===g.obsId)||!Object.hasOwn(SOURCES,g.source)||!AREAS.includes(g.area)||(g.material&&!Object.hasOwn(MATERIALS,g.material)))throw Error('Ungültiges Ziel.');for(const g of p.goals){for(const k of ['studentText','studentHelp','studentIcon','studentSourceText'])if(g[k]!==undefined&&!strings(g,[k]))throw Error('Ungültige Schülerfassung.')}for(let l of p.logs)if(!l||!safeId(l.id)||!strings(l,['id','goalId','date','author','delivered','result','support','evidence','judgement','next'])||!p.goals.some(g=>g.id===l.goalId))throw Error('Ungültiger Verlauf.')}return x.plans}
const areaLabel=a=>a==='Lern- und Arbeitsverhalten'?'Verhalten & Arbeiten':a;
function catalog(){if(catalogTab!=='bausteine')return legacyCatalog();return head('Auswählen · anpassen · fördern','Bausteindatenbank','Alle '+TEMPLATES.length+' Bausteine deines Auswahlkatalogs, nach Förderbereichen geordnet.')+`<div class="tabs">${[['bausteine','Förderbausteine'],['material','Materialvorlagen'],['quellen','Literatur & Evidenz']].map(([id,l])=>btn(l,'tab:'+id,catalogTab===id?'active':'')).join('')}</div>${picker()}<section class="panel"><h2>Förderbereich auswählen</h2><p class="sub">Mehrere Verhaltensweisen sind auswählbar – auch aus unterschiedlichen Bereichen.</p><div class="area-grid">${AREAS.map(a=>`<button data-action="filter:${a}" class="area-choice ${area===a?'selected':''}" aria-pressed="${area===a}"><span>${areaLabel(a)}</span><strong>${TEMPLATES.filter(t=>t.area===a).length}</strong></button>`).join('')}</div><label class="help" for="area-select">Förderbereich</label><select id="area-select"><option value="">Bitte wählen</option>${['Alle',...AREAS].map(a=>`<option value="${a}" ${area===a?'selected':''}>${a==='Alle'?'Alle Förderbereiche':a}</option>`).join('')}</select></section><div id="selection-bar"></div><label for="search" class="help">Bausteine durchsuchen</label><input id="search" class="search" type="search" placeholder="Beobachtung, Förderziel, Maßnahme oder Material suchen …" value="${esc(query)}"><div id="count" class="sub" style="margin:16px 0"></div>${focusObs?'<div class="hint">Bezug zur vorhandenen Beobachtung: Die Reihenfolge berücksichtigt Wortübereinstimmungen. Jede Auswahl bitte fachlich prüfen.</div>':''}<div class="catalog-grid" id="cards"></div><div class="hint">Die Formulierungen stammen vollständig aus deinem Auswahlkatalog (S. 3–17). Wähle nur tatsächlich beobachtetes Verhalten und passe es an die konkrete Situation an. Ein Forschungsbezug betrifft den Ansatz, nicht automatisch jede Maßnahme oder jedes Material.</div>`}
function renderCards(){let list=TEMPLATES.filter(t=>(area==='Alle'||t.area===area)&&[t.title,t.observation,t.goal,t.measures,t.materials].join(' ').toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de'))).sort((a,b)=>score(b)-score(a));$('#count').textContent=area?`${list.length} ${list.length===1?'Baustein':'Bausteine'} · ${areaLabel(area)}`:'Wähle oben einen Förderbereich.';$('#cards').innerHTML=!area?'<div class="empty span2">Zuerst den Förderbereich wählen. Danach kannst du mehrere passende Verhaltensweisen ankreuzen.</div>':list.map(t=>`<article class="catalog-card ${selectedTemplates.has(t.id)?'chosen':''}"><div class="row">${badge(t.area)}<small class="sub">Katalog S. ${t.catalogPage}</small></div><label class="pick-observation"><input type="checkbox" class="template-check" value="${t.id}" ${selectedTemplates.has(t.id)?'checked':''}><span><strong>${esc(t.title)}</strong><span>${esc(t.observation)}</span></span></label><p><strong>Mögliches Förderziel</strong><br>${esc(t.goal)}</p><p class="sub">${t.measureOptions.length} Maßnahmen · ${t.materialOptions.length} Materialien zur Auswahl</p><div class="actions flex">${btn('Alle Bausteine ansehen','template:'+t.id,'small','eye')}${t.research?btn('Forschungsbezug','source:'+t.research,'ghost small'):badge('Individuell erproben','gray')}</div></article>`).join('')||'<div class="empty span2">Keine passenden Treffer. Ändere den Suchbegriff oder Förderbereich.</div>';updateSelectionBar()}
function updateSelectionBar(){let bar=$('#selection-bar');if(!bar)return;bar.innerHTML=`<div class="selection-box"><div><strong>${selectedTemplates.size} ${selectedTemplates.size===1?'Verhaltensweise ausgewählt':'Verhaltensweisen ausgewählt'}</strong><div class="sub">Die Auswahl bleibt beim Wechsel des Förderbereichs erhalten.</div></div><div class="flex"><button data-action="batch" class="primary" ${selectedTemplates.size?'':'disabled'}>Maßnahmen auswählen & Plan erstellen</button>${selectedTemplates.size?btn('Auswahl leeren','clearselection','ghost small'):''}</div></div>`}
function templateDetails(id){let t=TEMPLATES.find(t=>t.id===id);openModal(t.title,`${badge(t.area)}<h3 style="margin-top:20px">Beobachtbares Verhalten</h3><p>${esc(t.observation)}</p><h3>Förderziel</h3><p>${esc(t.goal)}</p><h3>Maßnahmen</h3><ul>${t.measureOptions.map(m=>`<li>${esc(m)}</li>`).join('')}</ul><h3>Materialien / Hilfen</h3><ul>${t.materialOptions.map(m=>`<li>${esc(m)}</li>`).join('')}</ul><div class="hint">Originalbaustein aus deinem Auswahlkatalog, S. ${t.catalogPage}. ${t.research?'Forschungsbezug zum Ansatz: '+esc(SOURCES[t.research].short)+'. Die gesamte Kombination ist nicht separat evaluiert.':'Kein spezifischer Wirksamkeitsbeleg für diese Kombination verifiziert.'}</div><div class="dialogfooter">${plan().obs.length?btn('Für vorhandene Beobachtung nutzen','useexisting:'+id,'small'):''}${btn(selectedTemplates.has(id)?'Bereits ausgewählt':'Zur Auswahl hinzufügen','addselection:'+id,'primary','plus')}</div>`)}
function choiceList(t,kind){let options=kind==='m'?t.measureOptions:t.materialOptions;return `<div class="option-list">${options.map((x,i)=>`<label><input type="checkbox" name="${kind}-${t.id}" value="${i}"><span>${esc(x)}</span></label>`).join('')}</div>`}
function batchForm(){if(!selectedTemplates.size)return;let items=TEMPLATES.filter(t=>selectedTemplates.has(t.id)),p=plan();openModal('Auswahl zum Förderplan zusammenstellen',`<p><strong>${items.length} Verhaltensweisen</strong> für ${esc(p.code)}. Prüfe jede Beobachtung, passe das Ziel an und wähle die passenden Maßnahmen aus.</p>${items.length+p.goals.length>3?'<div class="hint warning">Mehrfachauswahl ist möglich. Priorisiere für einen Förderzeitraum möglichst zwei bis drei zentrale Ziele.</div>':''}<div class="form-grid">${field('Beobachtungsdatum *','batch-date',today(),'date')}${field('Überprüfung am *','batch-due',p.end,'date')}${field('Verantwortliche Person / Rolle *','batch-owner','')}${field('Häufigkeit und Dauer *','batch-frequency','','text','Gilt zunächst für alle ausgewählten Ziele; später einzeln bearbeitbar.')}</div>${items.map((t,i)=>`<details class="batch-item" ${i===0?'open':''}><summary>${i+1}. ${esc(t.title)} <span class="sub">${esc(t.area)}</span></summary><div class="batch-content">${field('Tatsächlich beobachtetes Verhalten *','b-'+t.id+'-text',t.observation,'textarea','Nur übernehmen, soweit es zutrifft; möglichst Häufigkeit und Unterstützung ergänzen.')}${field('Situation / Beobachtungsumfang *','b-'+t.id+'-context','','text','Fach, Aufgabe und Zahl der Beobachtungen.')}${field('Ausgangswert / aktueller Stand','b-'+t.id+'-baseline','')}${field('Stärken / gelingende Bedingungen','b-'+t.id+'-resource','')}${field('Individuelles Förderziel *','b-'+t.id+'-goal',t.goal,'textarea')}<fieldset><legend>Passende Maßnahmen auswählen *</legend>${choiceList(t,'m')}${field('Eigene Maßnahmen ergänzen','b-'+t.id+'-ownmeasures','','textarea')}</fieldset><fieldset><legend>Materialien / Hilfen auswählen</legend>${choiceList(t,'a')}${field('Eigene Materialien ergänzen','b-'+t.id+'-ownmaterials','','textarea')}</fieldset></div></details>`).join('')}<label class="confirm-observed"><input type="checkbox" name="observed-confirm">Die ausgewählten Verhaltensweisen wurden tatsächlich beobachtet und die Formulierungen geprüft.</label>${footer('Auswahl in den Förderplan übernehmen')}`,v=>{let fd=new FormData($('#dialogform'));try{const records=buildBatchRecords(items,fd,p);p.obs.push(...records.obs);p.goals.push(...records.goals);selectedTemplates.clear();save();closeDialog();go('plan');toast(`${records.goals.length} Förderziele mit ausgewählten Maßnahmen übernommen.`)}catch(e){toast(e.message)}})}
function buildBatchRecords(items,fd,p){const get=k=>String(fd.get(k)||'').trim();if(!['batch-date','batch-due','batch-owner','batch-frequency'].every(k=>get(k)))throw Error('Bitte Datum, Überprüfung, Zuständigkeit und Häufigkeit ergänzen.');if(get('batch-due')<p.start)throw Error('Die Überprüfung liegt vor dem Förderbeginn.');if(!fd.has('observed-confirm'))throw Error('Bitte bestätigen, dass die Verhaltensweisen tatsächlich beobachtet wurden.');let obs=[],goals=[];for(const t of items){let key='b-'+t.id+'-',text=get(key+'text'),context=get(key+'context'),goal=get(key+'goal'),criterion=get(key+'criterion');if(!text||!context||!goal)throw Error(`„${t.title}“: Beobachtung, Situation und Ziel ergänzen.`);let measures=fd.getAll('m-'+t.id).map(i=>t.measureOptions[Number(i)]).filter(Boolean);if(get(key+'ownmeasures'))measures.push(get(key+'ownmeasures'));if(!measures.length)throw Error(`„${t.title}“: Mindestens eine Maßnahme auswählen oder ergänzen.`);let materials=fd.getAll('a-'+t.id).map(i=>t.materialOptions[Number(i)]).filter(Boolean);if(get(key+'ownmaterials'))materials.push(get(key+'ownmaterials'));let o={id:uid(),date:get('batch-date'),area:t.area,text,context,baseline:get(key+'baseline'),resource:get(key+'resource'),templateId:t.id};obs.push(o);goals.push({id:uid(),obsId:o.id,templateId:t.id,area:t.area,title:t.title,text:goal,baseline:o.baseline,measures:measures.join('\n'),materials:materials.join('\n'),source:'praxis',research:t.research,material:t.material,catalogPage:t.catalogPage,frequency:get('batch-frequency'),owner:get('batch-owner'),due:get('batch-due'),criterion,status:'In Arbeit'})}return {obs,goals}}
function tableRows(p){return p.goals.map(g=>{let o=p.obs.find(o=>o.id===g.obsId),logs=p.logs.filter(l=>l.goalId===g.id).sort((a,b)=>a.date.localeCompare(b.date));return [g.area+'\n\n'+(o?.text||'Keine Beobachtung verknüpft.')+(g.baseline?'\n\nBisher dokumentierter Ausgangswert: '+g.baseline:'')+(o?.context?'\nSituation: '+o.context:'')+(o?.resource?'\nRessourcen: '+o.resource:''),g.title+'\n\n'+g.text,'Maßnahmen:\n'+g.measures+'\n\nMaterialien / Hilfen:\n'+(g.materials||'Keine ausgewählt.'),'Verantwortlich:\n'+(g.owner||'offen')+'\n\nHäufigkeit / Dauer:\n'+(g.frequency||'offen'),'Termin: '+date(g.due)+'\n\nStand: '+g.status+'\n\n'+(logs.length?logs.map(l=>date(l.date)+' – '+l.judgement+'\n'+l.result+'\nHilfen: '+l.support+'\nNächster Schritt: '+(l.next||'offen')).join('\n\n'):'Evaluation: noch nicht dokumentiert.') ]})}
const TABLE_HEADS=['Beobachtung / Ausgangslage','Förderziel','Maßnahmen & Materialien','Umsetzung','Überprüfung & Verlauf'];
function tableHTML(){let p=plan();return `<h1>Tabellarischer Förderplan${p.demo?' · Demofall':''}</h1><p><strong>${esc(p.code)}</strong> · Klasse ${esc(p.grade)||'offen'} · Förderschwerpunkt Lernen<br>Förderzeitraum: ${date(p.start)} – ${date(p.end)}</p><p><strong>Stärken:</strong> ${esc(p.strengths)||'offen'}<br><strong>Perspektive Kind:</strong> ${esc(p.voice)||'offen'}<br><strong>Schulischer Kontext:</strong> ${esc(p.context)||'offen'}<br><strong>Familiärer Kontext:</strong> ${esc(p.family)||'offen'}<br><strong>Bestehende außerschulische Förderung:</strong> ${esc(p.externalSupport)||'offen'}</p><table class="plan-table"><thead><tr>${TABLE_HEADS.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${tableRows(p).map(cells=>`<tr>${cells.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="print-note">Erstellt am ${date(today())} · Bausteine zur Förderplanung · Lernfortschritte nur anhand dokumentierter Verlaufsdaten einschätzen.</p>`}
function openTable(){openModal('Tabellenvorschau',`<div class="table-scroll">${tableHTML()}</div><div class="dialogfooter">${btn('PDF herunterladen','pdfplan','primary','download')}${btn('Tabelle drucken','printplan')}</div>`);$('#modal').classList.add('wide-dialog')}
function printTable(){document.body.classList.add('table-print');$('#print').innerHTML=tableHTML();window.print()}
window.addEventListener('afterprint',()=>document.body.classList.remove('table-print'));
document.addEventListener('change',e=>{if(e.target.id==='area-select'){area=e.target.value;render()}if(e.target.classList.contains('template-check')){if(e.target.checked)selectedTemplates.add(e.target.value);else selectedTemplates.delete(e.target.value);e.target.closest('.catalog-card').classList.toggle('chosen',e.target.checked);updateSelectionBar()}});

document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let [act,...rest]=el.dataset.action.split(':'),id=rest.join(':'),p=plan();switch(act){case'nav':go(id);break;case'new':profileForm(true);break;case'profile':profileForm();break;case'close':closeDialog();break;case'addobs':obsForm();break;case'editobs':obsForm(id);break;case'suggest':focusObs=id;area=p.obs.find(x=>x.id===id).area;query='';catalogTab='bausteine';go('catalog');break;case'template':templateDetails(id);break;case'useexisting':closeDialog();goalForm(null,id);break;case'addselection':selectedTemplates.add(id);closeDialog();render();toast('Baustein zur Auswahl hinzugefügt.');break;case'batch':batchForm();break;case'clearselection':selectedTemplates.clear();renderCards();break;case'browse':focusObs=null;catalogTab='bausteine';go('catalog');break;case'pdfplan':exportPlanPDF();break;case'tablepreview':openTable();break;case'editgoal':goalForm(id);break;case'customgoal':goalForm();break;case'filter':area=id;render();break;case'tab':catalogTab=id;render();break;case'source':openModal('Forschungsgrundlage',sourceHTML(id,SOURCES[id]||SOURCES.praxis));break;case'log':logForm(id);break;case'editlog':logForm(null,id);break;case'generate':if(p.report){openModal('Bericht neu ableiten','<p>Der vorhandene Bericht einschließlich deiner Textänderungen wird durch einen neuen Entwurf aus den aktuellen Daten ersetzt.</p>'+footer('Neu ableiten'),()=>{p.report=reportText();p.reportStamp=stamp();save();closeDialog();render()})}else{p.report=reportText();p.reportStamp=stamp();save();render()}break;case'printplan':printTable();break;case'rtfplan':download(rtf(planText()),'Foerderplan.rtf','application/rtf');break;case'printreport':printText((p.reportReviewed?'Fachlich geprüft\n\n':'Ungeprüfter Entwurf\n\n')+p.report);break;case'rtfreport':download(rtf((p.reportReviewed?'Fachlich geprüft\n\n':'Ungeprüfter Entwurf\n\n')+p.report),'Entwicklungsbericht.rtf','application/rtf');break;case'material':material(id);break;case'printmaterial':printText($('#material-text').value);break;case'rtfmaterial':download(rtf($('#material-text').value),'Foerdermaterial.rtf','application/rtf');break;case'settings':settings();break;case'backup':download(JSON.stringify(state,null,2),'Bausteine_zur_Foerderplanung_Sicherung_'+today()+'.json','application/json');toast('Sicherung zum Download bereitgestellt.');break;case'import':$('#import-file').click();break;case'adddemo':{let d=demo();state.plans.push(d);state.active=d.id;save();closeDialog();go('home');break}case'deleteplan':confirmAction('Förderplan löschen?','Der aktuelle Förderplan mit seinen Beobachtungen und Verlaufseinträgen wird aus diesem Browser gelöscht.',()=>{state.plans=state.plans.filter(x=>x.id!==p.id);if(!state.plans.length)state.plans=[blank()];state.active=state.plans[0].id;focusObs=null});break;case'deleteobs':if(p.goals.some(g=>g.obsId===id)){toast('Die Beobachtung ist mit einem Ziel verknüpft. Zuerst den Bezug im Ziel ändern.');break}confirmAction('Beobachtung löschen?','Die Beobachtung wird entfernt.',()=>p.obs=p.obs.filter(x=>x.id!==id));break;case'deletegoal':confirmAction('Förderziel löschen?','Dieses Ziel und die zugehörigen Verlaufseinträge werden entfernt.',()=>{p.goals=p.goals.filter(x=>x.id!==id);p.logs=p.logs.filter(x=>x.goalId!==id)});break;case'deletelog':confirmAction('Verlaufseintrag löschen?','Der Eintrag wird entfernt. Der Bericht muss anschließend aktualisiert werden.',()=>p.logs=p.logs.filter(x=>x.id!==id));break}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderCards()}if(e.target.id==='report-text'){plan().report=e.target.value;save();let c=$('#reviewed');if(c)c.checked=false}});
document.addEventListener('change',async e=>{if(e.target.id==='plan-select'){state.active=e.target.value;focusObs=null;selectedTemplates.clear();save(false);render()}if(e.target.id==='reviewed'){if(e.target.checked&&plan().reportStamp!==stamp()){e.target.checked=false;return toast('Die Datengrundlage wurde geändert. Bitte Bericht neu ableiten.')}plan().reportReviewed=e.target.checked;save(false)}if(e.target.id==='import-file'){let f=e.target.files[0];if(!f)return;if(f.size>5e6)return toast('Die Datei ist zu groß (maximal 5 MB).');try{let ps=validateImport(JSON.parse(await f.text()));ps=ps.map(p=>({...p,id:uid(),code:p.code+' (Import)',reportReviewed:false}));state.plans.push(...ps);state.active=ps[0].id;focusObs=null;save();closeDialog();go('home');toast(ps.length+' Förderpläne importiert.')}catch(err){toast('Import nicht möglich: '+err.message)}}});


